/**
 * رادار هواشناسی بارشی ایران — خواستهٔ کاربر (۲۰ نوامبر ۲۰۲۶، دوم):
 * «عکس رادار هواشناسی بارشی میخوام فقط ایران رو نشون بده و داخل عکس هم وضعیت فعلی و هم
 *  به شکل سایه مانند روش وضعیت چند ساعت آینده نمایش داده بشه به شکل رنگی که مثلا آبی برفه،
 *  نارنجی باران، بیرنگ آفتابی و... دقیقا مانند نقشه های حرفه ای هواشناسی اما فقط روی ایران».
 *
 * منبع داده: Open-Meteo (عمومی و بدون کلید API — همان پیش‌بینی‌ای که کارت‌های هواشناسی
 * شهرها از آن ساخته می‌شوند) روی گرید ~۰٫۷ درجه‌ای داخل مرز ایران (نمونه‌گیری نقطه‌ای).
 * مرز ایران: Natural Earth 50m، ساده‌شده با Douglas-Peucker (≈۰٫۰۲ درجه) — ثابت همین فایل.
 *
 * تصویر: فقط ایران — زمینهٔ تیرهٔ کانال، پیکان مرز، نشان‌های رنگی وضعیت «فعلی»
 * (آبی=برف، نارنجی/قرمز=بارانِ سبک→شدید، خاکستری کم‌رنگ=ابری، بی‌رنگ=آفتابی)
 * و «سایهٔ محو بزرگ‌تر» برای بارشِ ۳ ساعت آینده (فیلتر گاوسی) — سبک نقشه‌های
 * حرفه‌ای رادار. همهٔ توابع هندسه/دسته‌بندی/SVG خالص و تست‌پذیرند؛ فقط fetch زنده است.
 * شکست هر مرحله → null (فراخواننده صادقانه چیزی نمی‌فرستد — جایگزین نقشهٔ GIBS شد).
 */
import { mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { faDigits } from './daily';
import type { TripleDate } from './calendar';

// ---------- فونت‌پیکربندی پروژه‌ای — پیش از نخستین رندر sharp ----------
const PROJECT_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
if (!process.env.FONTCONFIG_FILE) {
  try { mkdirSync(join(PROJECT_ROOT, '.fc-cache'), { recursive: true }); } catch { /* بی‌اهمیت */ }
  process.env.FONTCONFIG_FILE = join(PROJECT_ROOT, '.fontconfig.conf');
}

// ---------- هندسهٔ بوم ----------

export const RADAR_W = 1100;
/** نسبت خطی EPSG:4326 — ۱۷ درجهٔ عرض / ۲۱ درجهٔ طول */
export const RADAR_MAP_H = Math.round((RADAR_W * 17) / 21); // ۸۹۰
export const RADAR_HEADER_H = 210;
export const RADAR_FOOTER_H = 50;
export const RADAR_TOTAL_H = RADAR_HEADER_H + RADAR_MAP_H + RADAR_FOOTER_H;

/** جعبهٔ جغرافیایی ایران + حاشیهٔ کوچک — عین نقشهٔ بارشی پیشین */
