/** پرتاب نقطه در حلقه (ray-casting) — روی مختصات جغرافیایی؛ خالص */
function pointInRing(lon: number, lat: number, ring: Ring): boolean {
  let inside = false;
  const n = ring.length;
  if (n < 3) return false;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const [xi, yi] = ring[i]!;
    const [xj, yj] = ring[j]!;
    if ((yi > lat) !== (yj > lat) && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/** نقطه داخل خاک ایران است؟ — هر حلقه (سرزمین اصلی + جزیره‌ها). خالص تست‌پذیر. */
export function pointInIran(lon: number, lat: number): boolean {
  for (const ring of IRAN_RINGS) if (pointInRing(lon, lat, ring)) return true;
  return false;
}

/** تبدیل درجه به پیکسل بومِ نقشه — بالا=شمال (y وارونه). خالص. */
export function lonLatToXY(lon: number, lat: number, w = RADAR_W, h = RADAR_MAP_H, margin = 6): [number, number] {
  const x = margin + ((lon - IRAN_BBOX.minLon) / (IRAN_BBOX.maxLon - IRAN_BBOX.minLon)) * (w - margin * 2);
  const y = margin + ((IRAN_BBOX.maxLat - lat) / (IRAN_BBOX.maxLat - IRAN_BBOX.minLat)) * (h - margin * 2);
  return [x, y];
}

/** گرید نقطه‌ای داخل خاک ایران — گام پیش‌فرض ۰٫۷ درجه (≈۷۵km — تفکیک نقشهٔ کشوری). خالص. */
export function buildIranGrid(stepDeg = 0.7): Array<{ lat: number; lon: number }> {
  const out: Array<{ lat: number; lon: number }> = [];
  const step = Math.max(0.25, Math.min(1.5, stepDeg));
  for (let lat = IRAN_BBOX.minLat + step / 2; lat <= IRAN_BBOX.maxLat; lat += step) {
    for (let lon = IRAN_BBOX.minLon + step / 2; lon <= IRAN_BBOX.maxLon; lon += step) {
      if (pointInIran(lon, lat)) out.push({ lat: Math.round(lat * 100) / 100, lon: Math.round(lon * 100) / 100 });
    }
  }
  return out;
}

// ---------- واکشی گرید Open-Meteo (بدون کلید) ----------

export interface RadarSample {
  precipitation: number;
  rain: number;
  snowfall: number;
  cloudCover?: number;
}

/** نشانی درخواست گرید — چندنقطه‌ای (لیست‌های جداشده با کاما). خالص تست‌پذیر. */
export function buildOpenMeteoGridUrl(lats: number[], lons: number[]): string {
  const p = new URLSearchParams({
    latitude: lats.map((v) => v.toFixed(2)).join(','),
    longitude: lons.map((v) => v.toFixed(2)).join(','),
    current: 'precipitation,rain,snowfall,cloud_cover',
    hourly: 'precipitation,rain,snowfall',
    forecast_hours: '4',
    timezone: 'Asia/Tehran',
  });
  return `https://api.open-meteo.com/v1/forecast?${p.toString()}`;
}

/** سالم‌سازی یک نقطه از پاسخ — نبود فیلد → صفر (هیچ NaN به رندر نمی‌رسد). خالص. */
export function num(v: unknown): number {
  const n = typeof v === 'number' ? v : Number(v);
  return Number.isFinite(n) && n > 0 ? n : 0;
}

// ---------- دسته‌بندی رنگ‌ها — «آبی برف، نارنجی باران، بی‌رنگ آفتابی» ----------

export type RadarKind = 'snow' | 'rain' | 'cloud' | 'clear';

/** دستهٔ یک نمونهٔ وضعیت — برف مقدم بر باران (برفِ آمیخته آبی دیده می‌شود)،
 *  بارش صفر + ابریِ ≥۶۵٪ = ابری، مابقی آفتابی (بی‌رنگ). level: شدت ۰..۲. خالص. */
export function classifyRadarSample(s: RadarSample | null | undefined): { kind: RadarKind; level: 0 | 1 | 2 } {
  if (!s) return { kind: 'clear', level: 0 };
  if (s.snowfall > 0) {
    const level: 0 | 1 | 2 = s.snowfall >= 1 ? 2 : s.snowfall >= 0.25 ? 1 : 0; // سانتی‌متر
    return { kind: 'snow', level };
  }
  const rain = Math.max(s.rain, s.snowfall > 0 ? 0 : s.precipitation);
  if (rain > 0) {
    const level: 0 | 1 | 2 = rain >= 5 ? 2 : rain >= 1 ? 1 : 0; // میلی‌متر
    return { kind: 'rain', level };
  }
  if ((s.cloudCover ?? 0) >= 65) return { kind: 'cloud', level: 0 };
  return { kind: 'clear', level: 0 };
}

/** رنگ نشان هر دسته/شدت — آبی‌ها برف، نارنجی→قرمز باران، خاکستری ابری، آفتابی بی‌رنگ. خالص. */
export function radarColor(kind: RadarKind, level: 0 | 1 | 2): string {
  if (kind === 'snow') return ['#7db9f5', '#3b82f6', '#1d4ed8'][level]!;
  if (kind === 'rain') return ['#fbd38d', '#f97316', '#dc2626'][level]!;
  if (kind === 'cloud') return '#8ea6bd';
  return '';
}

/** سلول گرید — وضعیت فعلی + وضعیت ۳ ساعت آینده (سایه) */
export interface RadarCell {
  lat: number;
  lon: number;
  cur: RadarSample;
  fc: RadarSample | null;
}

/** ضلع سلول «فعلی» بر پایهٔ شدت — px؛ مربع‌های گوشه‌گرد هم‌پوشان، سبک رادار حرفه‌ای. خالص. */
export function currentRadius(level: 0 | 1 | 2): number {
  return [32, 39, 46][level]!;
}

/** ضلع سلول سایهٔ پیش‌بینی — بزرگ‌تر و محوتر (تارشده با گاوسی). خالص. */
export function shadowRadius(level: 0 | 1 | 2): number {
  return [50, 60, 70][level]!;
}

// ---------- SVG — خالص و تست‌پذیر ----------

function esc(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function rtl(s: string): string {
  return `\u202B${s}\u202C`;
}

const FONT_FA = "'B Nazanin', Vazirmatn, sans-serif";

function iranBorderSvg(): string {
  const paths = IRAN_RINGS.map((ring) => {
    const d = ring.map(([lon, lat], i) => {
      const [x, y] = lonLatToXY(lon, lat);
      return `${i === 0 ? 'M' : 'L'} ${x.toFixed(1)} ${y.toFixed(1)}`;
    }).join(' ');
    return `<path d="${d} Z" fill="#142c47" stroke="#2f6fa8" stroke-width="2"/>`;
  }).join('\n  ');
  return paths;
}

/** مسیر خالص مرز ایران برای clipPath — دادهٔ بارش هرگز از خاک بیرون نمی‌زند (سبک رادار حرفه‌ای). خالص. */
function iranClipPathSvg(): string {
  const ds = IRAN_RINGS.map((ring) => {
    return ring.map(([lon, lat], i) => {
      const [x, y] = lonLatToXY(lon, lat);
      return `${i === 0 ? 'M' : 'L'} ${x.toFixed(1)} ${y.toFixed(1)}`;
    }).join(' ') + ' Z';
  }).join(' ');
  return `<clipPath id="iran">${ds ? `<path d="${ds}"/>` : ''}</clipPath>`;
}

/** خطوط راهنمای جغرافیایی — هر ۴ درجه، بسیار کم‌رنگ (سبک نقشه‌های حرفه‌ای). خالص. */
function graticuleSvg(): string {
  const L: string[] = [];
  for (let lat = 28; lat < 41; lat += 4) {
    const [, y] = lonLatToXY(50, lat);
    L.push(`<line x1="0" y1="${y.toFixed(1)}" x2="${RADAR_W}" y2="${y.toFixed(1)}" stroke="#1e3d5f" stroke-width="1" opacity="0.5"/>`);
  }
  for (let lon = 44; lon < 64; lon += 4) {
    const [x] = lonLatToXY(lon, 35);
    L.push(`<line x1="${x.toFixed(1)}" y1="0" x2="${x.toFixed(1)}" y2="${RADAR_MAP_H}" stroke="#1e3d5f" stroke-width="1" opacity="0.5"/>`);
  }
  return L.join('\n  ');
}

/** نشان‌های «فعلی» و «سایهٔ پیش‌بینی» — سلول‌های مربعی گوشه‌گرد هم‌پوشان (سبک رادار
 *  حرفه‌ای — پوشش پیوسته بدون حفرهٔ تیرهٔ میان دایره‌ها)؛ لایهٔ سایه با فیلتر گاوسی
 *  محوتر و بزرگ‌تر. آفتابی هیچ نشان ندارد (بی‌رنگ). خالص و تست‌پذیر. */
export function makeRadarCellsSvg(cells: RadarCell[]): { current: string; shadow: string } {
  const cur: string[] = [];
  const sh: string[] = [];
  for (const c of cells) {
    const [x, y] = lonLatToXY(c.lon, c.lat);
    const curC = classifyRadarSample(c.cur);
    if (curC.kind !== 'clear') {
      const fill = radarColor(curC.kind, curC.level);
      const s = currentRadius(curC.level);
      const op = curC.kind === 'cloud' ? 0.25 : 0.94;
      cur.push(`<rect x="${(x - s / 2).toFixed(1)}" y="${(y - s / 2).toFixed(1)}" width="${s}" height="${s}" rx="7" fill="${fill}" opacity="${op}"/>`);
    }
    const fcC = classifyRadarSample(c.fc);
    if (fcC.kind === 'snow' || fcC.kind === 'rain') {
      const fill = radarColor(fcC.kind, fcC.level);
      const s = shadowRadius(fcC.level);
      sh.push(`<rect x="${(x - s / 2).toFixed(1)}" y="${(y - s / 2).toFixed(1)}" width="${s}" height="${s}" rx="12" fill="${fill}"/>`);
    }
  }
  return { current: cur.join('\n  '), shadow: sh.join('\n  ') };
}

/** SVG کامل رادار — سربرگ/نقشه/راهنما/پانوشت. خالص و تست‌پذیر.
 *  timeFa = ساعت تهرانِ «اکنون» (فارسی) و fcLabel = برچسب ساعت آیندهٔ سایه‌ها. */
export function makeIranRadarSvg(date: TripleDate, cells: RadarCell[], timeFa: string, fcLabel: string): string {
  const { current, shadow } = makeRadarCellsSvg(cells || []);
  const PAD = 36;
  const W = RADAR_W;
  // راهنمای رنگ — یک ردیف اختصاصی با فاصلهٔ باز: برف | باران | ابری | آفتابی (راست‌به‌چپ)
  // و «سایهٔ محو = پیش‌بینی …» در سمت چپ همان ردیف — هیچ سطر موازی دیگری نیست (بدون هم‌پوشانی)
  const legendY = RADAR_HEADER_H - 42;
  const chip = (x: number, color: string, dashed = false) => `<rect x="${x}" y="${legendY - 13}" width="30" height="17" rx="8.5" fill="${dashed ? 'none' : color}"${dashed ? ` stroke="${color}" stroke-width="1.5" stroke-dasharray="5,4"` : ''}/>`;
  const txt = (x: number, s: string, anchor: 'start' | 'end' = 'end', fill = '#9fc3e8') =>
    `<text x="${x}" y="${legendY}" font-family="${FONT_FA}" font-size="21" fill="${fill}" text-anchor="${anchor}">${rtl(esc(s))}</text>`;
  const legend = `${txt(W - PAD, 'برف')}${chip(W - PAD - 90, '#3b82f6')}
  ${txt(W - PAD - 130, 'باران')}${chip(W - PAD - 220, '#f97316')}
  ${txt(W - PAD - 260, 'ابری')}${chip(W - PAD - 350, '#8ea6bd')}
  ${txt(W - PAD - 390, 'آفتابی')}${chip(W - PAD - 500, '#8ea6bd', true)}
  <text x="${PAD}" y="${legendY}" font-family="${FONT_FA}" font-size="21" fill="#8fb8d9" text-anchor="start">${rtl(esc(`سایهٔ محو = پیش‌بینی ${fcLabel} • رنگ تیره‌تر = بارش شدیدتر`))}</text>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${RADAR_TOTAL_H}" viewBox="0 0 ${W} ${RADAR_TOTAL_H}">
  <defs>
    <linearGradient id="hdr" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#0b2239"/><stop offset="1" stop-color="#164a75"/>
    </linearGradient>
    <filter id="soft" x="-60%" y="-60%" width="220%" height="220%">
      <feGaussianBlur stdDeviation="7"/>
    </filter>
    ${iranClipPathSvg()}
  </defs>
  <rect width="${W}" height="${RADAR_TOTAL_H}" fill="#0a1c30"/>
  <rect width="${W}" height="${RADAR_HEADER_H}" fill="url(#hdr)"/>
  <text x="${W - PAD}" y="64" font-family="${FONT_FA}" font-size="42" font-weight="700" fill="#ffffff" text-anchor="end">${rtl('رادار هواشناسی بارشی ایران')}</text>
  <text x="${W - PAD}" y="112" font-family="${FONT_FA}" font-size="25" fill="#9fc3e8" text-anchor="end">${rtl(esc(`${date.weekdayFa} ${date.shamsi} • ${date.miladi}`))}</text>
  <text x="${PAD}" y="64" font-family="${FONT_FA}" font-size="26" font-weight="700" fill="#ff6b6b" text-anchor="start">${rtl(esc(`ساعت ${timeFa} — وضعیت فعلی`))}</text>
  ${legend}
  <g transform="translate(0, ${RADAR_HEADER_H})">
    ${graticuleSvg()}
    ${iranBorderSvg()}
    <g clip-path="url(#iran)">
      <g filter="url(#soft)" opacity="0.30">${shadow}</g>
      ${current}
    </g>
  </g>
  <text x="${W - PAD}" y="${RADAR_TOTAL_H - 18}" font-family="${FONT_FA}" font-size="20" fill="#6f93b4" text-anchor="end">${rtl('رصدبان • فقط ایران')}</text>
  <text x="${PAD}" y="${RADAR_TOTAL_H - 18}" font-family="${FONT_FA}" font-size="20" fill="#6f93b4" text-anchor="start">${rtl('داده: Open-Meteo')}</text>
</svg>`;
}

// ---------- واکشی زنده + مونتاژ PNG ----------

export interface RadarPng {
  png: Buffer;
  width: number;
  height: number;
}

/** ساعت تهران «اکنون» به فارسی — «۱۴:۰۵». خالص. */
export function tehranClockFa(now = new Date()): string {
  const parts = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Asia/Tehran' }).format(now);
  return faDigits(parts);
}

/** برچسب ساعت آیندهٔ سایه‌ها — «۳ ساعت آینده» (+۳ ساعت از اکنون). خالص. */
export const RADAR_FC_LABEL = '۳ ساعت آینده';

/** پاسخ یک نقطهٔ Open-Meteo → جفت نمونهٔ (فعلی، +۳ساعت). خالص. */
export function parseOpenMeteoPoint(p: unknown): { cur: RadarSample; fc: RadarSample | null } | null {
  if (!p || typeof p !== 'object') return null;
  const o = p as {
    current?: { precipitation?: unknown; rain?: unknown; snowfall?: unknown; cloud_cover?: unknown };
    hourly?: { precipitation?: unknown[]; rain?: unknown[]; snowfall?: unknown[] };
  };
  if (!o.current) return null;
  const cur: RadarSample = {
    precipitation: num(o.current.precipitation),
    rain: num(o.current.rain),
    snowfall: num(o.current.snowfall),
    cloudCover: num(o.current.cloud_cover),
  };
  const h = o.hourly;
  if (Array.isArray(h?.precipitation) && h.precipitation.length >= 4) {
    const i = 3; // نخستین خانه = ساعت جاری → خانهٔ چهارم = +۳ ساعت
    const fc: RadarSample = {
      precipitation: num(h.precipitation[i]),
      rain: num(h.rain?.[i]),
      snowfall: num(h.snowfall?.[i]),
    };
    return { cur, fc };
  }
  return { cur, fc: null };
}

/** رادار بارشی ایران — گرید + واکشی + رندر. شکست هر مرحله → null (صادقانه). */
export async function fetchIranRadarPng(date: TripleDate): Promise<RadarPng | null> {
  try {
    const grid = buildIranGrid(0.7);
    if (grid.length < 20) return null;
    // گرید در چند تکهٔ ~۳۵۰نقطه‌ای — مهربانی با سرویس عمومی
    const cells: RadarCell[] = [];
    const CHUNK = 350;
    for (let off = 0; off < grid.length; off += CHUNK) {
      const part = grid.slice(off, off + CHUNK);
      const url = buildOpenMeteoGridUrl(part.map((g) => g.lat), part.map((g) => g.lon));
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 25_000);
      let json: unknown = null;
      try {
        const res = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0 (compatible; RaadbanBot/1.0; +https://github.com)' }, signal: ctrl.signal });
        if (!res.ok) return null;
        json = await res.json();
      } finally {
        clearTimeout(timer);
      }
      const arr = Array.isArray(json) ? json : [json];
      part.forEach((g, i) => {
        const parsed = parseOpenMeteoPoint(arr[i]);
        if (parsed) cells.push({ lat: g.lat, lon: g.lon, ...parsed });
      });
      await new Promise((r) => setTimeout(r, 250));
    }
    if (cells.length < 20) return null;
    const svg = makeIranRadarSvg(date, cells, tehranClockFa(), RADAR_FC_LABEL);
    const sharp = (await import('sharp')).default;
    const png = await sharp(Buffer.from(svg), { density: 72 }).png().toBuffer();
    const meta = await sharp(png).metadata();
    if (!meta.width || !meta.height || png.length < 15_000) return null;
    return { png, width: meta.width, height: meta.height };
  } catch {
    return null;
  }
}
